"use client";

import { useEffect, useState } from "react";
import axios from "axios";

interface Student {
  id: number;
  name: string;
  email: string;
  course: string;
  year: number;
}

export default function Students() {
  const [students, setStudents] = useState<Student[]>([]);
  const [form, setForm] = useState({
    id: null as number | null,
    name: "",
    email: "",
    course: "",
    year: ""
  });

  // Debug form changes
  useEffect(() => {
    console.log("Form :", form);
  }, [form]);

  // Fetch students
  const fetchStudents = async () => {
  try {
    const token = localStorage.getItem("accessToken");

    const res = await axios.get("http://localhost:5000/api/students", {
      headers: {
        Authorization: `Bearer ${token}`
      }
    });

    setStudents(res.data);

  } catch (error) {
    console.error("Error fetching students", error);
  }
};

useEffect(() => {
  const token = localStorage.getItem("accessToken");

  if (!token) {
    window.location.href = "/login";
  } else {
    fetchStudents();
  }
}, []);

  // CREATE + UPDATE
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const token = localStorage.getItem("accessToken");

    try {
      if (form.id) {
        // UPDATE
        await axios.put(
          `http://localhost:5000/api/students/${form.id}`,
          form,
          {
            headers: {
              Authorization: `Bearer ${token}`
            }
          }
        );
      } else {
        // CREATE
        await axios.post(
          "http://localhost:5000/api/students",
          form,
          {
            headers: {
              Authorization: `Bearer ${token}`
            }
          }
        );
      }

      fetchStudents();

      setForm({
        id: null,
        name: "",
        email: "",
        course: "",
        year: ""
      });

    } catch (error: any) {
      if (error.response) {
        alert(error.response.data.message.join("\n"));
      } else {
        alert("Something went wrong");
      }
    }
  };

  // DELETE
  const handleDelete = async (id: number) => {
    try {
      const token = localStorage.getItem("accessToken");

      await axios.delete(
        `http://localhost:5000/api/students/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );

      fetchStudents();
    } catch (error) {
      console.error("Delete error", error);
    }
  };

  // EDIT
  const handleEdit = (student: Student) => {
    setForm({
      id: student.id,
      name: student.name,
      email: student.email,
      course: student.course,
      year: student.year.toString()
    });
  };

 return (
  <div className="p-10 max-w-2xl mx-auto text-black">
    <h1 className="text-3xl font-bold mb-6 text-center">
      Student Database CRUD
    </h1>

      {/* FORM */}
      <form onSubmit={handleSubmit} className="space-y-3 mb-8">

        <input
          className="border p-2 w-full rounded"
          placeholder="Name"
          value={form.name}
          onChange={(e) =>
            setForm({ ...form, name: e.target.value })
          }
          required
        />

        <input
          className="border p-2 w-full rounded"
          placeholder="Email"
          value={form.email}
          onChange={(e) =>
            setForm({ ...form, email: e.target.value })
          }
          required
        />

        <input
          className="border p-2 w-full rounded"
          placeholder="Course"
          value={form.course}
          onChange={(e) =>
            setForm({ ...form, course: e.target.value })
          }
          required
        />

        <input
          type="number"
          className="border p-2 w-full rounded"
          placeholder="Year"
          value={form.year}
          onChange={(e) =>
            setForm({ ...form, year: e.target.value })
          }
          required
        />


        
        <button
          type="submit"
          className="btn-primary"
        >
          {form.id ? "Update Student" : "Add Student"}
        </button>
      </form>

      {/* STUDENT LIST */}
      <div className="space-y-4">
        {students.map((student) => (
          <div
            key={student.id}
            className="border p-4 rounded flex justify-between items-center shadow"
          >
            <div>
              <p className="font-semibold text-lg">{student.name}</p>
              <p>{student.email}</p>
              <p>{student.course}</p>
              <p>Year: {student.year}</p>
            </div>

            <div className="space-x-2">
              <button
                onClick={() => handleEdit(student)}
                className="bg-yellow-500 text-white px-3 py-1 rounded"
              >
                Edit
              </button>

              <button
                onClick={() => handleDelete(student.id)}
                className="bg-red-600 text-white px-3 py-1 rounded"
              >
                Delete
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}